(2622,	'_site_transient_community-events-62f74efccdc12e68b006700b27a1cd20',	'a:4:{s:9:\"sandboxed\";b:0;s:5:\"error\";N;s:8:\"location\";a:1:{s:2:\"ip\";s:12:\"106.72.158.0\";}s:6:\"events\";a:3:{i:0;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:103:\"初心者からプロまで歓迎！WordPress好きが集う【横浜 WordPress Meetup 交流会 #28】\";s:3:\"url\";s:65:\"https://www.meetup.com/kanagawa-wordpress-meetup/events/306370007\";s:6:\"meetup\";s:25:\"Kanagawa WordPress Meetup\";s:10:\"meetup_url\";s:49:\"https://www.meetup.com/kanagawa-wordpress-meetup/\";s:4:\"date\";s:19:\"2025-03-22 14:00:00\";s:8:\"end_date\";s:19:\"2025-03-22 17:00:00\";s:20:\"start_unix_timestamp\";i:1742619600;s:18:\"end_unix_timestamp\";i:1742630400;s:8:\"location\";a:4:{s:8:\"location\";s:16:\"横浜市, Japan\";s:7:\"country\";s:2:\"jp\";s:8:\"latitude\";d:35.448338;s:9:\"longitude\";d:139.64328;}}i:1;a:10:{s:4:\"type\";s:6:\"meetup\";s:5:\"title\";s:120:\"WordPressにコントリビューションその5　翻訳で貢献しようPart3-Chiba WordPress Meetup 25年3月の会\";s:3:\"url\";s:62:\"https://www.meetup.com/chiba-wordpress-meetup/events/306375965\";s:6:\"meetup\";s:22:\"Chiba WordPress Meetup\";s:10:\"meetup_url\";s:46:\"https://www.meetup.com/chiba-wordpress-meetup/\";s:4:\"date\";s:19:\"2025-03-23 13:30:00\";s:8:\"end_date\";s:19:\"2025-03-23 16:30:00\";s:20:\"start_unix_timestamp\";i:1742704200;s:18:\"end_unix_timestamp\";i:1742715000;s:8:\"location\";a:4:{s:8:\"location\";s:12:\"Chiba, Japan\";s:7:\"country\";s:2:\"jp\";s:8:\"latitude\";d:35.606727999999997;s:9:\"longitude\";d:140.10818;}}i:2;a:10:{s:4:\"type\";s:8:\"wordcamp\";s:5:\"title\";s:27:\"WordCamp Kansai 2025, JAPAN\";s:3:\"url\";s:33:\"https://kansai.wordcamp.org/2025/\";s:6:\"meetup\";N;s:10:\"meetup_url\";N;s:4:\"date\";s:19:\"2025-11-01 00:00:00\";s:8:\"end_date\";s:19:\"2025-11-02 00:00:00\";s:20:\"start_unix_timestamp\";i:1761922800;s:18:\"end_unix_timestamp\";i:1762009200;s:8:\"location\";a:4:{s:8:\"location\";s:12:\"Osaka, JAPAN\";s:7:\"country\";s:2:\"JP\";s:8:\"latitude\";d:34.704364699999999;